import importlib, sys
print("python:", sys.version)
for mod in ["openpyxl", "pandas", "xlsxwriter", "xlrd", "odf"]:
    try:
        m = importlib.import_module(mod)
        print(mod, "OK", getattr(m, "__version__", "?"))
    except Exception as e:
        print(mod, "MISSING:", type(e).__name__, e)

from openpyxl import load_workbook

path = "sales_data.xlsx"
wb = load_workbook(path, data_only=True)
ws = wb.active


def norm(v):
    return str(v).strip().lower() if v is not None else ""


hdr_cell = None
for r in range(1, min(ws.max_row, 10) + 1):
    for c in range(1, ws.max_column + 1):
        if norm(ws.cell(row=r, column=c).value) == "profit margin %":
            hdr_cell = (r, c)
            break
    if hdr_cell:
        break

if not hdr_cell:
    print("RESULT: no 'Profit Margin %' column found")
    print("Row1:", [ws.cell(row=1, column=c).value for c in range(1, ws.max_column + 1)])
    raise SystemExit(1)

hr, hc = hdr_cell
print("Header cell:", ws.cell(row=hr, column=hc).coordinate, "=", ws.cell(row=hr, column=hc).value)

vals, errs = [], []
for r in range(hr + 1, ws.max_row + 1):
    v = ws.cell(row=r, column=hc).value
    if v is None:
        continue
    s = str(v)
    if any(e in s for e in ("#REF!", "#DIV/0!", "#VALUE!", "#NAME?", "#N/A")):
        errs.append((r, s))
    else:
        vals.append(v)

print("Computed values:", len(vals), "| formula errors:", len(errs))
if errs:
    print("ERROR CELLS:", errs[:20])
if vals:
    num = [v for v in vals if isinstance(v, (int, float))]
    if num:
        print("Min:", min(num), "| Max:", max(num), "| Mean:", sum(num) / len(num))
    print("First 8:", vals[:8])
    print("Last 3:", vals[-3:])

